export function sanitizeCircleParagraphs(html: string, pageNum: number, data?: QuotationData): string {
  if (!html) return html;
  return html;
}

function replaceExactText(html: string, oldText: string, newText: string): string {
  if (!newText || oldText === newText) return html;
  const escaped = oldText.replace(/[.*+?^$${}()|[\]\\]/g, '\\$&');
  return html.replace(new RegExp(`(>[^<]*)${escaped}([^<]*<\\/div>)`, 'g'), `$1${newText}$2`);
}

export function renderCirclePdfPage(pageIdx: number, data: QuotationData): string {
  let html = CIRCLE_PDF_PAGES_RAW[pageIdx] || '';
  if (!html) return '';

  const formatINR = (val: number) => Number(val || 0).toLocaleString('en-IN');
  const clientName = data.clientName?.trim() || 'Mr. Mohan George';
  const projectCity = data.projectCity?.trim() || 'Chennai';
  const modelName = data.model?.trim() || 'Alpha Circle Lift';
  const offerNo = data.offerNo?.trim() || 'AE/QTN13052026-330';
  const offerDate = data.offerDate?.trim() || '13/05/2026';
  const bdmName = data.representativeName?.trim() || 'BDM Signatory';

  if (pageIdx === 0) {
    // PAGE 1: Cover
    html = html.replace('Name : Mr. Mohan George', 'Name : ' + clientName);
    html = html.replace('Project City : Chennai', 'Project City : ' + projectCity);
    html = html.replace('Model : Alpha Circle Lift', 'Model : ' + modelName);
  } else if (pageIdx === 1) {
    // PAGE 2: Intent Letter & About
    html = html.replace('AE/QTN13052026-330', offerNo);
    html = html.replace(': 13/05/2026', ': ' + offerDate);
    html = html.replace('Mr. Mohan George', clientName);
    if (data.subject) {
      html = html.replace('Supply, Install, test and commission of \nAlpha Circle Elevator.', data.subject);
    }
  } else if (pageIdx === 2) {
    // PAGE 3: Specifications & Signatures
    html = replaceExactText(html, 'Alpha Circle Lift', modelName);
    if (data.shaftType) html = replaceExactText(html, 'Indoor', data.shaftType);
    if (data.cabinWalls) html = replaceExactText(html, 'Standard Cabin', data.cabinWalls);
    if (data.machine) html = replaceExactText(html, 'Hydraulic', data.machine);
    if (data.doorAccess) html = replaceExactText(html, 'Automatic(One –Touch) with call reservation', data.doorAccess);
    if (data.ratedLoad) html = replaceExactText(html, 'Upto 180 Kgs (2 passengers)', data.ratedLoad);
    if (data.powerSupply) html = replaceExactText(html, 'Single Phase', data.powerSupply);
    if (data.speed) html = replaceExactText(html, 'Upto 0.5 m/s', data.speed);
    if (data.noOfStops) html = replaceExactText(html, '2 Stops/G+1', data.noOfStops);
    if (data.manufacturingWarranty) html = replaceExactText(html, '60 Months', data.manufacturingWarranty);
    if (data.hoistWayShaftSize) html = replaceExactText(html, '1150 mm', data.hoistWayShaftSize);
    if (data.finalStop || data.minFloorHeight) html = replaceExactText(html, '2850 mm', data.finalStop || data.minFloorHeight || '2850 mm');
    if (data.pitDepth) html = replaceExactText(html, '150 mm/ Ramp', data.pitDepth);

    // Signatures
    html = html.replace('>Mr/Ms<', `>${bdmName}<span style="display:none">`);
    html = html.replace('>Mr/ Ms<', `>${clientName}<span style="display:none">`);
  } else if (pageIdx === 3) {
    // PAGE 4: Cabin Specs, Pricing, Delivery & Terms
    if (data.clearOpening) html = replaceExactText(html, '600 mm', data.clearOpening);
    if (data.minFloorHeight) html = replaceExactText(html, '2010 mm', data.minFloorHeight);
    if (data.carSize) html = replaceExactText(html, '750 mm', data.carSize);
    if (data.ceiling) html = replaceExactText(html, 'Automatic LED lighting and cabin fan', data.ceiling);
    if (data.doorOpening) html = replaceExactText(html, 'Same side (in-line) and walk through (180°), 90° right or left', data.doorOpening);
    if (data.doorSpecifications) html = replaceExactText(html, 'Hinged on top left, door swings to the left (from inside the', data.doorSpecifications);
    if (data.copAndLop) html = replaceExactText(html, 'Push button call with precise leveling at each landing', data.copAndLop);
    if (data.battery) html = replaceExactText(html, 'Automatic descent to ground level at safety speed', data.battery);
    if (data.manufacturingWarranty) html = replaceExactText(html, '60-month limited warranty from installation', data.manufacturingWarranty + ' warranty from installation');

    const elevatorPriceNum = Number(data.elevatorPrice) || 1100000;
    const discountNum = Number(data.elevatorDiscountPrice || 0);
    const hasDiscount = Boolean(discountNum > 0);
    const finalPriceNum = hasDiscount ? Math.max(0, elevatorPriceNum - discountNum) : elevatorPriceNum;
    const mrpPriceNum = elevatorPriceNum;
    const gstPct = data.gstRate !== undefined ? data.gstRate : 18;

    html = replaceExactText(html, 'Rs. 13,00,000 + 18% GST', `Rs. ${formatINR(mrpPriceNum)} + ${gstPct}% GST`);
    html = replaceExactText(html, 'Rs. 11,00,000 + 18% GST', `Rs. ${formatINR(finalPriceNum)} + ${gstPct}% GST`);

    if (data.deliveryTime) {
      html = replaceExactText(html, '120 days post confirmation on drawings and finishes', data.deliveryTime);
    }
    if (data.warranty) {
      html = replaceExactText(html, '05 years - manufacturing warranty + 1 Year Free Maintenance', data.warranty);
    }
    if (data.paymentTerms?.booking) {
      html = replaceExactText(html, 'Booking amount - 30%', 'Booking amount - ' + data.paymentTerms.booking);
    }
    if (data.paymentTerms?.production) {
      html = replaceExactText(html, 'Production amount - 40%', 'Production amount - ' + data.paymentTerms.production);
    }
    if (data.paymentTerms?.readiness) {
      html = replaceExactText(html, 'Readiness notification- 30%', 'Readiness notification- ' + data.paymentTerms.readiness);
    }

    // Signatures
    html = html.replace('>Mr/Ms<', `>${bdmName}<span style="display:none">`);
    html = html.replace('>Mr/ Ms<', `>${clientName}<span style="display:none">`);
  } else if (pageIdx === 4) {
    // PAGE 5: Terms & Conditions, Acceptance
    const deliveryDays = data.deliveryDays || (data.deliveryTime ? parseDeliveryDays(data.deliveryTime) : 120) || 120;
    html = html.replace('ready within 120 days', `ready within ${deliveryDays} days`);

    const clientSignName = data.clientSignatoryName?.trim() || clientName;
    const clientDate = data.clientSignDate?.trim() || offerDate;
    const alphaSignName = data.alphaSignatoryName?.trim() || bdmName;
    const alphaDate = data.alphaSignDate?.trim() || offerDate;

    // Client Acceptance Name and Date
    html = html.replace('<div class="t c24" style="z-index:1308;transform:matrix(1,0,0,1,52.1,839.23)">Name: </div>',
      `<div class="t c24" style="z-index:1308;transform:matrix(1,0,0,1,52.1,839.23)">Name: <strong style="color:#001f5d;">${clientSignName}</strong></div>`);
    html = html.replace('<div class="t c24" style="z-index:1340;transform:matrix(1,0,0,1,52.1,922.4)">Date:</div>',
      `<div class="t c24" style="z-index:1340;transform:matrix(1,0,0,1,52.1,922.4)">Date: ${clientDate}</div>`);

    // Alpha Elevators Acceptance Name and Date
    html = html.replace('<div class="t c24" style="z-index:1314;transform:matrix(1,0,0,1,373.51,839.23)">Name:</div>',
      `<div class="t c24" style="z-index:1314;transform:matrix(1,0,0,1,373.51,839.23)">Name: <strong style="color:#001f5d;">${alphaSignName}</strong></div>`);
    html = html.replace('<div class="t c24" style="z-index:1345;transform:matrix(1,0,0,1,373.51,922.4)">Date:</div>',
      `<div class="t c24" style="z-index:1345;transform:matrix(1,0,0,1,373.51,922.4)">Date: ${alphaDate}</div>`);
  }

  return html;
}
